mapper.select:
select d.dept_id from zqzt_sys_dept d left join zqzt_sys_role_dept rd on d.dept_id = rd.dept_id where rd.role_id = #{roleId}
and d.dept_id not in (select d.parent_id from zqzt_sys_dept d inner join zqzt_sys_role_dept rd on d.dept_id = rd.dept_id and rd.role_id = #{roleId})
order by d.parent_id, d.order_num
